148	  return (
149	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
150	      {steps.map((s, i) => (
151	        <div key={s} className="flex items-center gap-2">
152	          <span
153	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
154	              i === step
155	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
156	                : i < step
157	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
158	                  : "border-white/10 text-slate-500"
159	            }`}
160	          >
161	            {i < step ? "✓" : i + 1}
162	          </span>
163	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
164	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
165	        </div>
166	      ))}
167	    </div>
168	  );
