171	const ORDER_STEPS = ["Domain", "Plan", "Review"];
172	
173	function OrderPanel({
174	  suggestedDomains,
175	  plans,
176	  balanceCents,
177	  annualDiscountPct,
178	  email,
179	}: {
180	  suggestedDomains: string[];
181	  plans: PlanOpt[];
182	  balanceCents: number;
183	  annualDiscountPct: number;
184	  email: string;
185	}) {
186	  const [step, setStep] = useState(0);
187	  const [domain, setDomain] = useState(suggestedDomains[0] ?? "");
188	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
189	  // Annual is the recommended, better-value default; monthly stays one click away.
190	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
191	  const [error, setError] = useState<string | null>(null);
192	  const [ok, setOk] = useState(false);
193	  const [pending, start] = useTransition();
194	  // "Apply my balance" — mirrors the VPS/hosting wizards. Default ON when there's a
195	  // balance to apply; off routes the whole charge to a card. The server recomputes the
196	  // identical split (lib/wallet-split.ts), so displayed === charged.
197	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
198	  // Mirrors DeployWizard's stripePhase/checkoutSession split: "loading"/"error"
199	  // track the embedded Payment step's own session request; "ready" is implied
200	  // by checkoutSession being non-null.
201	  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");
202	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
203	  const isLast = step === ORDER_STEPS.length - 1;
204	  const domainBlocker = !domain.trim() ? "Enter a domain to continue." : null;
205	
206	  const selected = plans.find((p) => p.id === planId);
207	  // Email plans are seeded monthly, so priceCents is the per-month base. Price the
208	  // chosen term through the SAME formula the server charges (termPriceCents).
209	  const termCharge = selected ? termPriceCents(selected.priceCents, termMonths, annualDiscountPct) : 0;
210	  // Business Email has no first-month-free, so the amount due today IS the term charge.
211	  const split = walletSplit({ dueCents: termCharge, balanceCents, useWallet });
212	  const cardCents = split.cardCents;
213	  const walletApplied = split.walletApplied;
214	  const registered = new Set(suggestedDomains.map((d) => d.toLowerCase()));
215	  const trimmed = domain.trim().toLowerCase();
216	  const isExternal = trimmed.length > 0 && !registered.has(trimmed);
217	
218	  function submit() {
219	    if (!domain.trim()) {
220	      setError("Enter a domain.");
221	      return;
222	    }
223	    setError(null);
224	    setOk(false);
225	    setStripePhase("loading");
226	    start(async () => {
227	      const res = await orderEmailHosting(domain.trim(), planId, termMonths, useWallet);
228	      // A card leg is due — mount the embedded Payment step. On success Stripe
229	      // navigates the top window to the confirm route, which credits the card to the
230	      // wallet and creates the subscription.
231	      if (res && "checkout" in res) {
232	        setCheckoutSession({ clientSecret: res.checkout.clientSecret, publishableKey: res.checkout.publishableKey });
233	        setStripePhase("idle");
234	        return;
235	      }
236	      if (res?.error) {
237	        setError(res.error);
238	        setStripePhase("error");
239	      } else if (res?.ok) {
240	        setOk(true);
241	        // Fire-and-forget "email" conversion (→ Meta Subscribe + the Google Ads
242	        // email label). Best-effort: a no-op until consent + the pixel load.
243	        try {
244	          (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.("email", { value: termCharge / 100, currency: "USD" });
245	        } catch {
246	          /* ignore */
247	        }
248	      }
249	    });
250	  }
251	
252	  // A card leg is due once the customer reaches Review — same condition VPS
253	  // uses to decide whether PaymentStep mounts instead of the plain fallback.
254	  const showPaymentStep = isLast && cardCents > 0;
255	
256	  // A Custom Checkout session is priced at the moment it's created. If the
257	  // customer flips "Apply my balance" AFTER one exists, its stamped amount is
258	  // stale — drop it so PaymentStep asks for a fresh one, rather than letting
259	  // them confirm a payment for the wrong total. Same guard DeployWizard uses.
260	  const prevCardCentsRef = useRef(cardCents);
261	  useEffect(() => {
262	    if (checkoutSession && prevCardCentsRef.current !== cardCents) {
263	      setCheckoutSession(null);
264	      setStripePhase("idle");
265	    }
266	    prevCardCentsRef.current = cardCents;
267	  }, [cardCents, checkoutSession]);
268	
269	  // PaymentStep's PayPal/Coinbase support isn't wired for Business Email yet
270	  // (no product need identified) — these stubs are never invoked since
271	  // `paypal`/`coinbaseReady` are both off, which hides those method rows
272	  // entirely.
273	  async function paypalUnavailable() {
274	    return { error: "PayPal isn't available for Business Email yet." };
275	  }
276	
277	  return (
278	    <section>
279	      <h2 className="mb-3 text-lg font-semibold text-white">Add email hosting</h2>
280	      <div className="card wizard-shell space-y-4">
281	        <Stepper step={step} steps={ORDER_STEPS} />
282	
283	        {error && (
284	          <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
285	            {error}
286	          </div>
287	        )}
288	        {ok && (
289	          <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
290	            Subscription created. Add mailboxes below — and, for a domain registered elsewhere, finish
291	            the DNS setup shown on the subscription.
292	          </div>
293	        )}
294	
295	        {/* Step 1 — Domain */}
296	        {step === 0 && (
297	          <div>
298	            <label className="label">Domain</label>
299	            <input
300	              className="input"
301	              value={domain}
302	              onChange={(e) => setDomain(e.target.value)}
303	              placeholder="yourdomain.com"
304	              list="nxeon-email-domains"
305	              autoCapitalize="none"
306	              autoCorrect="off"
307	              spellCheck={false}
308	            />
309	            <datalist id="nxeon-email-domains">
310	              {suggestedDomains.map((d) => (
311	                <option key={d} value={d} />
