823	/**
824	 * Per-domain SPF / DKIM / DMARC / MX self-check.
825	 *
826	 * WHY: "my mail goes to spam" was undiagnosable from inside the product. The
827	 * platform owner hit exactly this and had to diagnose it with an external
828	 * third-party tool, so every customer in the same position had no route at all.
829	 *
830	 * Two things this panel must never do, because both would make it the codebase's
831	 * recurring defect in a new place — a surface reporting an outcome it never
832	 * verified, here telling someone their mail is fine while it goes to spam:
833	 *
834	 *   1. Report a status the server did not derive from DNS. Every badge below
835	 *      comes from `checkEmailDeliverability`, which reads the zone's own
836	 *      AUTHORITATIVE nameservers (this host's `hosts: files myhostname dns`
837	 *      nsswitch order can answer a lookup out of /etc/hosts while looking like a
838	 *      real query — that produced one confidently wrong diagnosis already).
839	 *   2. Round a partial answer up. `unknown` renders as its own slate state, not
840	 *      as a pass, and the nameservers actually queried are printed so the result
841	 *      is auditable rather than taken on trust.
842	 *
843	 * Not auto-run: each check is several outbound DNS queries plus one Mailcow call,
844	 * and the customer has to be looking at it for the answer to be useful.
845	 */
846	function DeliverabilityPanel({
847	  subscriptionId,
848	  domainName,
849	}: {
850	  subscriptionId: string;
851	  domainName: string;
852	}) {
853	  const [report, setReport] = useState<DeliverabilityReport | null>(null);
854	  const [error, setError] = useState<string | null>(null);
855	  const [pending, start] = useTransition();
856	
857	  function run() {
858	    setError(null);
859	    start(async () => {
860	      const res = await checkEmailDeliverability(subscriptionId);
861	      if (res?.error) {
862	        setError(res.error);
863	        setReport(null);
864	      } else if (res?.report) {
865	        setReport(res.report);
