165	  // stripePhase/checkoutSession split.
166	  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");
167	
168	  // Only accept a session as the result of an EXPLICIT submit (armed in
169	  // requestStripeSession/the Deploy button), so a stale session can never
170	  // apply on its own (e.g. after a back-button remount).
171	  const submittedRef = useRef(false);
172	  useEffect(() => {
173	    if (submittedRef.current) {
174	      submittedRef.current = false;
175	      if (state?.checkout) {
176	        // The "game" conversion is fired at FULFILMENT (PurchaseTracker, with the real
177	        // charged value + transaction_id) — NOT here at checkout-start, which would
178	        // count customers who abandon at the payment step.
179	        setCheckoutSession(state.checkout);
180	      } else {
181	        setCheckoutSession(null);
