import { chromium } from "/opt/nxeon-staging/node_modules/playwright/index.mjs";

const shotDir = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/shots";
import fs from "node:fs";
fs.mkdirSync(shotDir, { recursive: true });

const browser = await chromium.launch();
const context = await browser.newContext({ bypassCSP: true });
const page = await context.newPage();
page.on("console", (msg) => { if (msg.type() === "error") console.log("[console error]", msg.text()); });
page.on("pageerror", (err) => console.log("[pageerror]", err.message));

try {
  console.log("Navigating to login...");
  await page.goto("https://staging.nxeon.cloud/login", { waitUntil: "networkidle" });
  await page.screenshot({ path: `${shotDir}/00-login.png` });

  // Try to find email/password fields
  const emailInput = page.locator('input[type="email"], input[name="email"]').first();
  const passInput = page.locator('input[type="password"], input[name="password"]').first();
  await emailInput.fill("claude-audit-2026@nxeon.test");
  await passInput.fill("AuditPass123!");
  await page.screenshot({ path: `${shotDir}/01-login-filled.png` });
  await Promise.all([
    page.waitForNavigation({ waitUntil: "networkidle" }).catch(() => {}),
    page.locator('button[type="submit"]').first().click(),
  ]);
  await page.waitForTimeout(1500);
  console.log("URL after login:", page.url());
  await page.screenshot({ path: `${shotDir}/02-after-login.png` });

  console.log("Navigating to email dashboard...");
  await page.goto("https://staging.nxeon.cloud/dashboard/email", { waitUntil: "networkidle" });
  await page.screenshot({ path: `${shotDir}/03-email-page.png`, fullPage: true });

  // Check leftover heading gone
  const oldHeading = await page.locator('text="Add email hosting"').count();
  console.log("Leftover 'Add email hosting' heading count (expect 0):", oldHeading);

  // Step 0: domain step icons/copy
  const iconBlurbs = await page.locator('text="A domain in your account"').count();
  console.log("Beginner-friendly domain copy present (expect >=1):", iconBlurbs);
  await page.screenshot({ path: `${shotDir}/04-domain-step.png`, fullPage: true });

  // Advance: click Continue (sticky cart or normal button)
  const domainInput = page.locator('input[placeholder="yourdomain.com"]').first();
  await domainInput.fill("claude-verify-test.com");
  await page.screenshot({ path: `${shotDir}/05-domain-filled.png`, fullPage: true });

  const continueBtn = page.locator('button:has-text("Continue")').first();
  await continueBtn.click();
  await page.waitForTimeout(800);
  await page.screenshot({ path: `${shotDir}/06-plan-step.png`, fullPage: true });

  // Step 1: plan step -> click continue again to reach Review
  const continueBtn2 = page.locator('button:has-text("Continue")').first();
  await continueBtn2.click();
  await page.waitForTimeout(1000);
  await page.screenshot({ path: `${shotDir}/07-review-step.png`, fullPage: true });

  console.log("URL at review:", page.url());

  // Look for "Change" next to billing term
  const changeBtn = page.locator('button:has-text("Change")').first();
  const changeCount = await page.locator('button:has-text("Change")').count();
  console.log("Change button count:", changeCount);

  const urlBeforeChange = page.url();
  if (changeCount > 0) {
    await changeBtn.click();
    await page.waitForTimeout(500);
    console.log("URL after clicking Change (should be same):", page.url(), "same as before:", page.url() === urlBeforeChange);
    await page.screenshot({ path: `${shotDir}/08-term-picker-revealed.png`, fullPage: true });

    // Check TermLadder cards visible now
    const termCards = await page.locator('text=/Annual|Monthly|Biennial|Triennial/i').count();
    console.log("Term option text occurrences visible after Change click:", termCards);

    // Check for discount badge "Save"
    const saveBadge = await page.locator('text=/Save \\d+%/').count();
    console.log("Save X% badge count:", saveBadge);
  }

  // Sticky cart presence
  const stickyCart = await page.locator('.sticky.bottom-4').count();
  console.log("Sticky cart element count:", stickyCart);

} catch (e) {
  console.error("ERROR during verification:", e);
} finally {
  await browser.close();
}

