import { chromium } from "/opt/nxeon-staging/node_modules/playwright/index.mjs";
import fs from "node:fs";

const shotDir = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/shots";
fs.mkdirSync(shotDir, { recursive: true });

const browser = await chromium.launch();
const context = await browser.newContext({ bypassCSP: true });
const page = await context.newPage();
page.on("pageerror", (err) => console.log("[pageerror]", err.message));

try {
  await page.goto("https://staging.nxeon.cloud/login", { waitUntil: "networkidle" });
  const cookieBtn = page.locator('button:has-text("Got it")');
  if (await cookieBtn.count()) await cookieBtn.click();
  await page.locator('input[type="email"]').first().fill("claude-audit-2026@nxeon.test");
  await page.locator('input[type="password"]').first().fill("AuditPass123!");
  await Promise.all([
    page.waitForNavigation({ waitUntil: "networkidle" }).catch(() => {}),
    page.locator('button:has-text("Sign In")').first().click(),
  ]);

  await page.goto("https://staging.nxeon.cloud/dashboard/email", { waitUntil: "networkidle" });

  const domainInput = page.locator('input[placeholder="yourdomain.com"]').first();
  await domainInput.fill("claude-cardpath-test.com");
  await page.locator('button:has-text("Continue")').first().click();
  await page.waitForTimeout(600);
  await page.locator('button:has-text("Continue")').first().click();
  await page.waitForTimeout(800);

  // On Review step now. Uncheck "Apply my balance" to force the card path (PaymentStep).
  const walletCheckbox = page.locator('input[type="checkbox"]').first();
  if (await walletCheckbox.count()) {
    const checked = await walletCheckbox.isChecked();
    console.log("wallet checkbox present, checked=", checked);
    if (checked) {
      await walletCheckbox.uncheck();
      await page.waitForTimeout(1500); // allow stripe session request / re-render
    }
  } else {
    console.log("no wallet checkbox found (maybe no balance)");
  }

  await page.screenshot({ path: `${shotDir}/10-review-card-path.png`, fullPage: true });

  const stickyCartVisible = await page.locator('.sticky.bottom-4').count();
  console.log("Sticky cart present while PaymentStep showing (expect 0):", stickyCartVisible);

  const saveBadge = await page.locator('text=/Save \\d+%/').count();
  console.log("Save X% badge count in PaymentStep summary:", saveBadge);

  const changeBtn = page.locator('button:has-text("Change")');
  const changeCount = await changeBtn.count();
  console.log("Change button count:", changeCount);
  const urlBefore = page.url();
  if (changeCount > 0) {
    await changeBtn.first().click();
    await page.waitForTimeout(500);
    console.log("URL unchanged after Change click:", page.url() === urlBefore, page.url());
    await page.screenshot({ path: `${shotDir}/11-term-picker-in-payment.png`, fullPage: true });
    const termLadderCards = await page.locator('text=/Annual|Biennial|Triennial/i').count();
    console.log("TermLadder cards visible:", termLadderCards);
  }
} catch (e) {
  console.error("ERROR:", e);
} finally {
  await browser.close();
}

