1	"use client";
2	
3	import { useEffect, useRef, useState } from "react";
4	import { placeHostingOrder, startHostingCardSetup, checkHostingSubdomain } from "@/lib/actions-hosting";
5	import { finalizeCardSetup } from "@/lib/actions-payment-method";
6	import { termPriceCents, ANNUAL_TERM_MONTHS, DEFAULT_ANNUAL_DISCOUNT_PCT, PRODUCT_TERMS, vpsTerm } from "@/lib/billing-terms";
7	import { extraDiskCentsAt, EXTRA_DISK_STEP_GB, EXTRA_DISK_MAX_ADD_GB, EXTRA_DISK_ONE_WAY_NOTE, EXTRA_DISK_DEFAULT_PER_GB_CENTS } from "@/lib/extra-disk";
8	import { TermLadder } from "@/components/customer/TermLadder";
9	import { StripeCheckoutModal } from "@/components/customer/StripeCheckoutModal";
10	import { PaymentStep } from "@/components/customer/PaymentStep";
11	import { WizardReassuranceCard } from "@/components/customer/WizardReassuranceCard";
12	import { walletSplit } from "@/lib/wallet-split";
13	import { recommendHostingPlan } from "@/lib/hosting/recommend";
14	import { useCurrency } from "@/components/currency/CurrencyContext";
15	import { convertAndFormat, DEFAULT_CURRENCY } from "@/lib/currency";
16	import { trackDeployStep, trackDeployError } from "@/lib/deploy-funnel-client";
17	
18	/* --------------------------------------------------------------- types --- */
19	
20	export type WizardPlan = {
21	  id: string;
22	  name: string;
23	  priceCents: number;
24	  diskGB: number;
25	  maxSites: number;
26	  maxDatabases: number;
27	  bandwidthTB: number;
28	  mailboxes: number;
29	  freeMigration: boolean;
30	  featured: boolean;
31	  tagline: string;
32	};
33	
34	type AppOpt = { slug: string; name: string; needsDb: boolean; blurb?: string; logoPath?: string; logoHex?: string };
35	
36	// USD formatter — this wizard's 2-decimal style ("$5.00"). Used verbatim for the
37	// USD display path (byte-for-byte unchanged) and for the "billed in USD" note.
38	const usd = (c: number) => `$${(c / 100).toFixed(2)}`;
39	
40	/** sessionStorage key for the in-progress order — survives the Stripe card round-trip. */
41	const DRAFT_KEY = "nxeon.hosting.deploy.draft.v1";
42	type Draft = {
43	  step: number;
44	  planId: string;
45	  termMonths: number;
46	  domainMode: "temp" | "own";
47	  domain: string;
48	  /** The chosen free-subdomain label — MUST persist across the card-setup round-trip,
49	   *  else a customer who typed "testing" gets the auto-derived name after adding a card. */
50	  subLabel: string;
51	  extraDiskGB: number;
52	  appSlug: string;
53	};
54	
55	/**
56	 * The one-month first-month-free credit, computed EXACTLY like the server's
57	 * `firstMonthCreditCents` (kept inline so this client file never imports the
58	 * db-backed promo module). A 1-month term is wholly free; a longer term credits a
59	 * single month. The server recomputes the real debit with the same formula, so
60	 * displayed === charged.
61	 */
62	function firstMonthCredit(fullCents: number, months: number): number {
63	  if (months <= 1) return fullCents;
64	  return Math.min(fullCents, Math.round(fullCents / months));
65	}
66	
67	function Stepper({ step, steps }: { step: number; steps: string[] }) {
68	  return (
69	    <div className="mb-6 flex flex-wrap items-center gap-2 text-xs">
70	      {steps.map((s, i) => (
71	        <div key={s} className="flex items-center gap-2">
72	          <span
73	            className={`flex h-6 w-6 items-center justify-center rounded-full border text-[11px] font-semibold ${
74	              i === step
75	                ? "border-brand-400 bg-brand-500/20 text-brand-200"
76	                : i < step
77	                  ? "border-emerald-500/40 bg-emerald-500/15 text-emerald-300"
78	                  : "border-white/10 text-slate-500"
79	            }`}
80	          >
81	            {i < step ? "✓" : i + 1}
82	          </span>
83	          <span className={i === step ? "text-white" : "text-slate-500"}>{s}</span>
84	          {i < steps.length - 1 && <span className="mx-1 text-slate-700">→</span>}
85	        </div>
86	      ))}
87	    </div>
88	  );
89	}
90	
91	/* -------------------------------------------------------------- wizard --- */
92	
93	export function HostingDeployWizard({
94	  plans,
95	  apps,
96	  annualDiscountPct = DEFAULT_ANNUAL_DISCOUNT_PCT,
97	  firstMonthFree = false,
98	  balanceCents,
99	  hasCard,
100	  cardLabel,
101	  stripeReady,
102	  tempSubdomainBase,
103	  extraDiskPerGbCents = EXTRA_DISK_DEFAULT_PER_GB_CENTS,
104	  email,
105	}: {
106	  plans: WizardPlan[];
107	  apps: AppOpt[];
108	  annualDiscountPct?: number;
109	  firstMonthFree?: boolean;
110	  balanceCents: number;
111	  /** A renewal-capable card is already on file (charged off-session at renewal). */
112	  hasCard: boolean;
113	  cardLabel: string | null;
114	  /** Stripe is configured, so we can capture a card at all. */
115	  stripeReady: boolean;
116	  /** Base zone for the free temporary subdomain, e.g. "nxeon.cloud". */
117	  tempSubdomainBase: string;
118	  /** Price per extra GB / month (cents) — the same add-on rate VPS uses. */
119	  extraDiskPerGbCents?: number;
120	  /** The account's email — PaymentStep's receipt/invoice-email display. */
121	  email: string;
122	}) {
123	  // Steps: Install is only shown when there's an app catalog to pick from.
124	  const hasApps = apps.length > 0;
125	  const steps = ["Plan", "Domain", ...(hasApps ? ["Install"] : []), "Add-ons", "Review"];
126	  const [step, setStep] = useState(0);
127	
128	  // Deploy-funnel: record reaching each wizard step (de-duped per session).
129	  useEffect(() => {
130	    trackDeployStep("hosting", steps[step] ?? String(step), step);
131	    // eslint-disable-next-line react-hooks/exhaustive-deps
132	  }, [step]);
133	
134	  // DISPLAY-ONLY price formatter. USD renders byte-for-byte as before; any other
135	  // selected display currency converts the USD-cents amount for on-screen reference
136	  // only. Everything sent to placeHostingOrder (and the nxTrack value) stays USD.
137	  const { currency, rate } = useCurrency();
138	  const money = (c: number) =>
139	    currency === DEFAULT_CURRENCY ? usd(c) : convertAndFormat(c, currency, rate);
140	
141	  const [planId, setPlanId] = useState(plans[0]?.id ?? "");
142	  const [termMonths, setTermMonths] = useState(ANNUAL_TERM_MONTHS);
143	  const [domainMode, setDomainMode] = useState<"temp" | "own">("temp");
144	  const [domain, setDomain] = useState("");
145	  // Optional customer-chosen free-subdomain label. Empty => the server auto-derives
146	  // `<username>.<base>`. When the customer types one we live-check availability so a
147	  // taken/invalid label is caught before the order (the order re-checks atomically).
148	  const [subLabel, setSubLabel] = useState("");
149	  const [subCheck, setSubCheck] = useState<{ status: "idle" | "checking" | "ok" | "bad"; reason?: string }>({ status: "idle" });
150	  const [extraDiskGB, setExtraDiskGB] = useState(0);
151	  const [appSlug, setAppSlug] = useState("");
152	
153	  // A card the customer just saved via the Stripe round-trip flips this true
154	  // without a page reload, so the Review step stops asking for one.
155	  const [savedCard, setSavedCard] = useState(hasCard);
156	  // "Apply my balance" — mirrors the VPS wizard. Default ON when there's a balance to
157	  // apply; turning it off routes the whole amount due today to a card. The server
158	  // recomputes the identical split (lib/wallet-split.ts), so displayed === charged.
159	  const [useWallet, setUseWallet] = useState(balanceCents > 0);
160	
161	  const [busy, setBusy] = useState(false);
162	  const [error, setError] = useState("");
163	  const [cardBusy, setCardBusy] = useState(false);
164	  const [cardNote, setCardNote] = useState("");
165	  // `addCard`'s setup-mode session (capture a renewal card, no charge) — this is a
166	  // genuinely different Stripe primitive from a Custom Checkout payment session
167	  // (mode:setup vs mode:payment, still on the OLD embedded_page ui_mode), so it
168	  // keeps using the popup StripeCheckoutModal rather than PaymentStep, which is
169	  // built around confirming a real payable Custom Checkout session.
170	  const [cardSetupCheckout, setCardSetupCheckout] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
171	  // `place()`'s Custom Checkout session (paying the card leg of an order) — feeds
172	  // the embedded PaymentStep, mirroring VPS/Game/Email.
173	  const [checkoutSession, setCheckoutSession] = useState<{ clientSecret: string; publishableKey: string } | null>(null);
174	  const [stripePhase, setStripePhase] = useState<"idle" | "loading" | "error">("idle");
175	  const [restoredAfterSetup, setRestoredAfterSetup] = useState(false);
176	
177	  // ONE idempotency token per wizard mount. A double-click is stopped by `busy`;
178	  // this token is the server-side guard against a network retry creating a second
179	  // account (placeHostingOrder → FulfilledSession UNIQUE). A user-driven retry
180	  // after a failure reuses it safely (the server clears a FAILED marker).
181	  const idemRef = useRef<string>("");
182	  if (!idemRef.current) idemRef.current = makeToken();
183	
184	  const plan = plans.find((p) => p.id === planId) ?? null;
185	  const curLabel = steps[step];
186	  const isLast = step === steps.length - 1;
187	
188	  /* ----- pricing (all DB-fed; the server recomputes the debit identically) -- */
189	  const planTermCents = plan ? termPriceCents(plan.priceCents, termMonths, annualDiscountPct) : 0;
190	  // Extra storage add-on: priced per GB/mo over the term, and NEVER discounted by the
191	  // first-month-free promo (mirrors the server — the credit applies to the plan only).
192	  const extraTermCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGbCents) * termMonths;
193	  const fullTermCents = planTermCents + extraTermCents;
194	  const creditCents = firstMonthFree ? firstMonthCredit(planTermCents, termMonths) : 0;
195	  const dueTodayCents = Math.max(0, planTermCents - creditCents) + extraTermCents;
196	  // What the account renews at — the full term price (plan + storage), promo aside.
197	  const renewalCents = fullTermCents;
198	  const perMonthCents = Math.round(planTermCents / Math.max(1, termMonths));
199	  const termWord = termMonths === ANNUAL_TERM_MONTHS ? "year" : termMonths === 1 ? "month" : `${termMonths} mo`;
200	
201	  // Wallet/card split for the amount due today — identical math to the server
202	  // (placeHostingOrder → walletSplit), so what's shown here === what's charged.
203	  const split = walletSplit({ dueCents: dueTodayCents, balanceCents, useWallet });
204	  const cardCents = split.cardCents;
205	  const walletApplied = split.walletApplied;
206	
207	  // Can we bill the renewal? A saved card OR a wallet already holding a renewal's
208	  // worth OR a card leg on THIS order (the card is saved for renewals via
209	  // setup_future_usage). Mirrors the server: a card-funded order needs no separate
210	  // renewal method.
211	  const renewalMethodOk = savedCard || balanceCents >= renewalCents || cardCents > 0;
212	  // A card leg is due at Review — PaymentStep mounts instead of the plain
213	  // fallback, same condition VPS/Game/Email use.
214	  const showPaymentStep = isLast && cardCents > 0;
215	
216	  // A Custom Checkout session is priced at the moment it's created. If the
217	  // customer flips "Apply my balance" AFTER one exists, its stamped amount is
218	  // stale — drop it so PaymentStep asks for a fresh one. Same guard as the
219	  // other wizards.
220	  const prevCardCentsRef = useRef(cardCents);
221	  useEffect(() => {
222	    if (checkoutSession && prevCardCentsRef.current !== cardCents) {
223	      setCheckoutSession(null);
224	      setStripePhase("idle");
225	    }
226	    prevCardCentsRef.current = cardCents;
227	  }, [cardCents, checkoutSession]);
228	
229	  /* ----- Stripe card round-trip (draft save + restore) ---------------------- */
230	  useEffect(() => {
231	    let sid = "";
232	    try {
233	      sid = new URLSearchParams(window.location.search).get("card_setup") ?? "";
234	    } catch {
235	      /* no URL access */
236	    }
237	    if (!sid) return;
238	    // Pull our draft back so the customer lands where they left off.
239	    let d: Draft | null = null;
240	    try {
241	      const raw = sessionStorage.getItem(DRAFT_KEY);
242	      sessionStorage.removeItem(DRAFT_KEY);
243	      if (raw) d = JSON.parse(raw) as Draft;
244	    } catch {
245	      d = null;
246	    }
247	    if (d) {
248	      if (plans.some((p) => p.id === d.planId)) setPlanId(d.planId);
249	      if (PRODUCT_TERMS.some((t) => t.months === d.termMonths)) setTermMonths(d.termMonths);
250	      if (d.domainMode === "temp" || d.domainMode === "own") setDomainMode(d.domainMode);
251	      if (typeof d.domain === "string") setDomain(d.domain);
252	      if (typeof d.subLabel === "string") setSubLabel(d.subLabel);
253	      if (Number.isFinite(d.extraDiskGB)) setExtraDiskGB(Math.max(0, Math.min(EXTRA_DISK_MAX_ADD_GB, Math.round(d.extraDiskGB))));
254	      if (apps.some((a) => a.slug === d.appSlug)) setAppSlug(d.appSlug);
255	    }
256	    setRestoredAfterSetup(true);
257	    setStep(steps.length - 1); // land on Review
258	    if (sid === "canceled") {
259	      setCardNote("Card setup was cancelled — you weren’t charged. Add a card to enable renewals, or use your wallet.");
260	      return;
261	    }
262	    // Finalise the saved card, then reflect it on the Review step.
263	    (async () => {
264	      const res = await finalizeCardSetup(sid);
265	      if (res.ok) {
266	        setSavedCard(true);
267	        setCardNote(`Card saved${res.label ? ` — ${res.label}` : ""}. Your renewals will bill to it.`);
268	        // Fire-and-forget "card" conversion (→ Meta AddPaymentInfo + the Google Ads
269	        // card label). Best-effort: a no-op until consent + the pixel load.
270	        try {
271	          (window as unknown as { nxTrack?: (k: string, p?: Record<string, unknown>) => void }).nxTrack?.("card", {});
272	        } catch {
273	          /* ignore */
274	        }
275	      } else {
276	        setCardNote(res.error ?? "We couldn’t save that card. Try again or use your wallet.");
277	      }
278	    })();
279	    // Mount-only restore.
280	    // eslint-disable-next-line react-hooks/exhaustive-deps
281	  }, []);
282	
283	  function saveDraft() {
284	    try {
285	      const d: Draft = { step, planId, termMonths, domainMode, domain, subLabel, extraDiskGB, appSlug };
286	      sessionStorage.setItem(DRAFT_KEY, JSON.stringify(d));
287	    } catch {
288	      /* storage disabled — the card flow still works, it just won't restore */
289	    }
290	  }
291	
292	  async function addCard() {
293	    setCardBusy(true);
294	    setCardNote("");
295	    saveDraft();
296	    try {
297	      const res = await startHostingCardSetup();
298	      if (res.clientSecret && res.publishableKey) {
299	        // Open the embedded card modal on THIS page — no redirect to Stripe.
300	        setCardSetupCheckout({ clientSecret: res.clientSecret, publishableKey: res.publishableKey });
301	        return;
302	      }
303	      setCardNote(res.error ?? "We couldn’t start card setup just now. Please try again.");
304	    } catch {
305	      setCardNote("We couldn’t start card setup just now. Please try again.");
306	    } finally {
307	      setCardBusy(false);
308	    }
309	  }
310	
311	  /* ----- domain validity (client-side friendliness; server re-validates) ---- */
312	  const domainTrim = domain.trim().toLowerCase();
313	  const domainLooksValid = /^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,}$/.test(domainTrim);
314	  const domainBlocker =
315	    domainMode === "own" && !domainLooksValid
316	      ? domainTrim.length === 0
317	        ? "Enter the domain you want to host, or switch to a free temporary subdomain."
318	        : "Enter a valid domain (e.g. example.com)."
319	      : null;
320	
321	  // Live availability check for a chosen free subdomain (debounced). An empty label
322	  // is allowed — the server auto-derives `<username>.<base>` — so only a typed label
323	  // that isn't confirmed available blocks the flow.
324	  const subLabelTrim = subLabel.trim().toLowerCase();
325	  useEffect(() => {
326	    if (domainMode !== "temp") {
327	      setSubCheck({ status: "idle" });
328	      return;
329	    }
330	    const label = subLabel.trim().toLowerCase();
331	    if (!label) {
332	      setSubCheck({ status: "idle" });
333	      return;
334	    }
335	    setSubCheck({ status: "checking" });
336	    let cancelled = false;
337	    const t = setTimeout(async () => {
338	      try {
339	        const r = await checkHostingSubdomain(label);
340	        if (!cancelled) setSubCheck(r.available ? { status: "ok" } : { status: "bad", reason: r.reason });
341	      } catch {
342	        if (!cancelled) setSubCheck({ status: "bad", reason: "Couldn’t check right now — try again." });
343	      }
344	    }, 400);
345	    return () => {
346	      cancelled = true;
347	      clearTimeout(t);
348	    };
349	  }, [subLabel, domainMode]);
350	
351	  const subdomainBlocker =
352	    domainMode === "temp" && subLabelTrim.length > 0 && subCheck.status !== "ok"
353	      ? subCheck.status === "checking"
354	        ? "Checking availability…"
355	        : subCheck.reason ?? "Pick an available subdomain."
356	      : null;
357	
358	  const canContinue = curLabel === "Domain" ? !domainBlocker && !subdomainBlocker : true;
359	  const canPlace = !!planId && !busy && !domainBlocker && !subdomainBlocker;
360	
361	  async function place() {
362	    if (!plan) return;
363	    setBusy(true);
364	    setError("");
365	    setStripePhase("loading");
366	    // Deploy-funnel: the customer submitted the final Review, so an order (a wallet
367	    // charge, or the renewal-method gate) is about to be attempted — record REACHED-
368	    // PAYMENT as a step at the tail (after Review). De-duped per session; completion
369	    // is now recorded server-side in placeHostingOrder (userId-keyed), so this wizard
370	    // no longer fires trackDeployComplete.
371	    trackDeployStep("hosting", "Payment", steps.length);
372	    try {
373	      const res = await placeHostingOrder({
374	        planId,
375	        domain: domainMode === "own" ? domainTrim : undefined,
376	        subdomainLabel: domainMode === "temp" && subLabelTrim ? subLabelTrim : undefined,
377	        extraDiskGB: extraDiskGB || undefined,
378	        termMonths,
379	        appSlug: appSlug || undefined,
380	        idempotencyKey: idemRef.current,
381	        useWallet,
382	      });
383	      // A card leg is due — mount the embedded Stripe checkout. On success Stripe
384	      // navigates the top window to the confirm route, which credits the card to the
385	      // wallet, places the account (debiting it) and lands the customer on it.
386	      if ("checkout" in res) {
387	        setCheckoutSession({ clientSecret: res.checkout.clientSecret, publishableKey: res.checkout.publishableKey });
388	        setStripePhase("idle");
