import { chromium } from "/opt/nxeon-staging/node_modules/playwright/index.mjs";
import fs from "node:fs";

const shotDir = "/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/shots";
fs.mkdirSync(shotDir, { recursive: true });

const browser = await chromium.launch();
const context = await browser.newContext({ bypassCSP: true });
const page = await context.newPage();
page.on("pageerror", (err) => console.log("[pageerror]", err.message));

try {
  await page.goto("https://staging.nxeon.cloud/login", { waitUntil: "networkidle" });
  const cookieBtn = page.locator('button:has-text("Got it")');
  if (await cookieBtn.count()) await cookieBtn.click();
  await page.locator('input[type="email"]').first().fill("claude-audit-2026@nxeon.test");
  await page.locator('input[type="password"]').first().fill("AuditPass123!");
  await Promise.all([
    page.waitForNavigation({ waitUntil: "networkidle" }).catch(() => {}),
    page.locator('button:has-text("Sign In")').first().click(),
  ]);

  await page.goto("https://staging.nxeon.cloud/dashboard/games/deploy", { waitUntil: "networkidle" }).catch(async () => {
    // fallback path guess
    await page.goto("https://staging.nxeon.cloud/dashboard/deploy?product=game", { waitUntil: "networkidle" });
  });
  await page.screenshot({ path: `${shotDir}/20-game-start.png`, fullPage: true });
  console.log("URL:", page.url());

  // Pick first game (poster tile)
  const gameTiles = page.locator('button[aria-pressed]');
  const gameCount = await gameTiles.count();
  console.log("Game tile count:", gameCount);
  if (gameCount > 0) {
    await gameTiles.first().click();
    await page.waitForTimeout(800);
  }
  await page.screenshot({ path: `${shotDir}/21-plan-step.png`, fullPage: true });

  // Pick first tier card
  const tierCards = page.locator('button.card.card-hover');
  const tierCount = await tierCards.count();
  console.log("Tier card count:", tierCount);
  if (tierCount > 0) {
    await tierCards.first().click();
    await page.waitForTimeout(400);
  }

  // Sticky cart should now show on Plan step
  const stickyCartOnPlan = await page.locator('.sticky.bottom-4').count();
  console.log("Sticky cart visible on Plan step (expect 1):", stickyCartOnPlan);
  await page.screenshot({ path: `${shotDir}/22-plan-tier-selected.png`, fullPage: true });

  // Continue via sticky cart button (should say Continue)
  const stickyContinue = page.locator('.sticky.bottom-4 button:has-text("Continue")');
  if (await stickyContinue.count()) {
    await stickyContinue.first().click();
  } else {
    await page.locator('button:has-text("Continue")').first().click();
  }
  await page.waitForTimeout(600);
  await page.screenshot({ path: `${shotDir}/23-settings-step.png`, fullPage: true });

  // Continue to Review
  const stickyContinue2 = page.locator('.sticky.bottom-4 button:has-text("Continue")');
  if (await stickyContinue2.count()) {
    await stickyContinue2.first().click();
  } else {
    await page.locator('button:has-text("Continue")').first().click();
  }
  await page.waitForTimeout(1000);
  await page.screenshot({ path: `${shotDir}/24-review-step.png`, fullPage: true });
  console.log("URL at review:", page.url());

  // Uncheck wallet if present to force card path
  const walletCheckbox = page.locator('input[type="checkbox"]').first();
  if (await walletCheckbox.count()) {
    const checked = await walletCheckbox.isChecked();
    console.log("wallet checkbox checked:", checked);
    if (checked) {
      await walletCheckbox.uncheck();
      await page.waitForTimeout(1500);
    }
  }
  await page.screenshot({ path: `${shotDir}/25-review-card-path.png`, fullPage: true });

  const stickyCartInPayment = await page.locator('.sticky.bottom-4').count();
  console.log("Sticky cart present during PaymentStep (expect 0):", stickyCartInPayment);

  const saveBadge = await page.locator('text=/Save \\d+%/').count();
  console.log("Save X% badge count:", saveBadge);

  const changeBtn = page.locator('button:has-text("Change")');
  const changeCount = await changeBtn.count();
  console.log("Change button count:", changeCount);
  const urlBefore = page.url();
  if (changeCount > 0) {
    await changeBtn.first().click();
    await page.waitForTimeout(500);
    console.log("URL unchanged after Change click:", page.url() === urlBefore);
    await page.screenshot({ path: `${shotDir}/26-term-picker-revealed.png`, fullPage: true });
    const termCards = await page.locator('text=/Annual|Biennial|Triennial/i').count();
    console.log("TermLadder cards visible:", termCards);
  }
} catch (e) {
  console.error("ERROR:", e);
} finally {
  await browser.close();
}

